    "mock.reminder": "Υπενθύμιση",
    "product.kicker": "Περισσότερο από task management",
    "product.title": "FOCUS · RHYTHM · MOMENTS",
    "product.lead": "Το FORYMO δεν παρουσιάζεται ως ακόμη ένας task manager. Οργανώνει την ημέρα σου σε τρία επίπεδα: τι αξίζει την προσοχή σου, τι επαναλαμβάνεται και χτίζει τον ρυθμό σου και τι πρέπει να συμβεί τη σωστή στιγμή.",
    "features.today.title": "MOMENTS — Η ημέρα σου",
    "features.today.body": "Η Ημέρα σου φέρνει τις σωστές εργασίες, συνήθειες και υπενθυμίσεις σε μία εικόνα, ώστε να βλέπεις τι έχει σημασία τώρα.",
    "features.tasks.title": "FOCUS — Εργασίες",
    "features.tasks.body": "Οι Εργασίες μετατρέπουν την προσοχή σε πράξη, κρατώντας καθαρό και ορατό ό,τι αξίζει την εστίασή σου.",
    "features.routines.title": "RHYTHM — Συνήθειες",
    "features.routines.body": "Οι Συνήθειες δίνουν δομή σε όσα επαναλαμβάνονται και βοηθούν τις σταθερές ενέργειες να γίνουν μέρος της καθημερινής σου ροής.",
    "features.reminders.title": "MOMENTS — Υπενθυμίσεις",
    "features.reminders.body": "Οι Υπενθυμίσεις συνδέουν μια ενέργεια με τη στιγμή που χρειάζεται την προσοχή σου.",
    "features.backup.title": "Αντίγραφα ασφαλείας & επαναφορά",
    "features.backup.body": "Δημιούργησε επαληθευμένα αντίγραφα ασφαλείας και επανάφερε τον χώρο εργασίας σου με σιγουριά όταν χρειαστεί.",
    "features.control.title": "Ένα σύστημα, υπό τον έλεγχό σου",
    "features.control.body": "Focus, Rhythm και Moments λειτουργούν μαζί σε έναν κατανοητό χώρο εργασίας, ενώ τα πραγματικά δεδομένα σου παραμένουν υπό τον δικό σου έλεγχο.",
    "how.kicker": "Πώς λειτουργεί το FORYMO",
    "how.title": "Από την προσοχή, στον ρυθμό, στη σωστή στιγμή.",
    "how.lead": "Το FORYMO συνδέει όσα πρέπει να κάνεις, όσα θέλεις να επαναλαμβάνεις και όσα πρέπει να εμφανίζονται τη σωστή στιγμή — χωρίς να μετατρέπει την ημέρα σου σε άκαμπτο σύστημα.",
    "how.s1h": "Κατάγραψε",
    "how.s1b": "Πρόσθεσε την εργασία, τη συνήθεια ή την υπενθύμιση όσο είναι ακόμη φρέσκια στο μυαλό σου.",
    "how.s2h": "Δες καθαρά",
    "how.s2b": "Χρησιμοποίησε την Ημέρα σου ως βασική οθόνη εργασίας, αντί να ψάχνεις σε ασύνδετες λίστες.",
    "how.s3h": "Προχώρησε",
    "how.s3b": "Ολοκλήρωσε ό,τι έχει σημασία, ενημέρωσε την κατάσταση και κράτησε ορατό το επόμενο βήμα.",
    "how.s4h": "Προστάτεψε",
    "how.s4b": "Διατήρησε επαληθευμένα αντίγραφα ασφαλείας ώστε να μπορείς να επαναφέρεις τον χώρο εργασίας σου όταν χρειαστεί.",
    "guide.kicker": "ΟΔΗΓΙΕΣ ΧΡΗΣΗΣ FORYMO",
    "guide.title": "Επίλεξε μια λειτουργία και δες ακριβώς πώς χρησιμοποιείται.",
    "guide.lead": "Γνώρισε κάθε ενότητα του FORYMO για Windows. Επίλεξε μια λειτουργία για να δεις τον σκοπό, τη ροή και τα βασικά χειριστήριά της.",
    "desktop.tag": "Κύρια εφαρμογή",
